import{_ as o,a as n,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · 单元 1 语法总结 · 情态动词的意义与形式至动名词与动词搭配","description":"L1–L24 规则、例句、易错点。","frontmatter":{"title":"第二册：实践与进步 · 单元 1 语法总结 · 情态动词的意义与形式至动名词与动词搭配","description":"L1–L24 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-2/unit-01/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 1 语法总结","summary":"L1–L24 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 1 语法总结 · 冠词与可数性至间接引语与视角转换","link":"/life/english/new-concept/book-2/unit-01/grammar-part-02"},"next":{"text":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 1 语法总结 · 冠词与可数性至间接引语与视角转换","link":"/life/english/new-concept/book-2/unit-01/grammar-part-02"},"next":{"text":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/grammar-part-03.md","filePath":"life/english/new-concept/book-2/unit-01/grammar-part-03.md"}'),i={name:"life/english/new-concept/book-2/unit-01/grammar-part-03.md"};function r(l,e,s,c,p,g){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-单元-1-语法总结-·-情态动词的意义与形式至动名词与动词搭配" tabindex="-1">第二册：实践与进步 · 单元 1 语法总结 · 情态动词的意义与形式至动名词与动词搭配 <a class="header-anchor" href="#第二册-实践与进步-·-单元-1-语法总结-·-情态动词的意义与形式至动名词与动词搭配" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 1 语法总结 · 情态动词的意义与形式至动名词与动词搭配&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-01/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元复习与自测</a></p><h2 id="情态动词的意义与形式" tabindex="-1">情态动词的意义与形式 <a class="header-anchor" href="#情态动词的意义与形式" aria-label="Permalink to &quot;情态动词的意义与形式 {#情态动词的意义与形式}&quot;">​</a></h2><p>can、could、may、might、must 等情态动词后接动词原形，否定一般直接加 not，不需要 do。它们可能表示能力、许可、义务或推测，必须根据上下文区分；could 不总是过去时间，也能表示委婉请求或较弱的可能性。must not 表示禁止，do not have to 表示没有必要，二者意义完全不同。判断语气时先问说话人在提出要求还是评价证据。本课应用：Could you move ...? 是礼貌请求，不是在询问过去能力。No parking 则是一条简短规则，两者在语气和句法上不同。</p><p>can、could、may、might、must 等情态动词后接动词原形，否定一般直接加 not，不需要 do。它们可能表示能力、许可、义务或推测，必须根据上下文区分；could 不总是过去时间，也能表示委婉请求或较弱的可能性。must not 表示禁止，do not have to 表示没有必要，二者意义完全不同。判断语气时先问说话人在提出要求还是评价证据。本课应用：may become available 只说明有可能，不能改写为一定会有。could buy 在具体过去情景中不一定表示成功买到，成功结果可明确写 managed to buy。</p><p>can、could、may、might、must 等情态动词后接动词原形，否定一般直接加 not，不需要 do。它们可能表示能力、许可、义务或推测，必须根据上下文区分；could 不总是过去时间，也能表示委婉请求或较弱的可能性。must not 表示禁止，do not have to 表示没有必要，二者意义完全不同。判断语气时先问说话人在提出要求还是评价证据。本课应用：could be worse 表一种较坏的可能情形，并不说明那件更坏的事真的发生。谈真实损失时用具体过去式，不把安慰语当成事实报告。</p><p><strong>L16 原创例句：</strong> Could you move your car away from the entrance, please?</p><p>请把车从入口处移开，好吗？</p><p><strong>L19 原创例句：</strong> Two seats may become available if someone cancels.</p><p>如果有人取消预订，可能会空出两个座位。</p><p><strong>L24 原创例句：</strong> I lost my wallet, but someone returned it that evening.</p><p>我丢了钱包，但那天晚上有人把它送回了。</p><p><strong>易错：</strong> Could you to move 多了 to；could 是情态动词，后接原形。</p><p>may to become 错误；情态动词后用原形，也不能把 may 解读成确定承诺。</p><p>someone 作主语按单数处理；someone have 应改为 someone has。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-016">Lesson 16</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-019">Lesson 19</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-024">Lesson 24</a></p><h2 id="动名词与动词搭配" tabindex="-1">动名词与动词搭配 <a class="header-anchor" href="#动名词与动词搭配" aria-label="Permalink to &quot;动名词与动词搭配 {#动名词与动词搭配}&quot;">​</a></h2><p>动词的 -ing 形式可像名词一样作主语或宾语，常出现在 enjoy、avoid、finish 等动词之后，以及介词之后。它仍能带自己的宾语或状语。另一些动词通常接 to 不定式，不能按中文意思随意互换；stop、remember、try 等词接两种形式时意思还可能改变。遇到 to 先判断它是不定式标记还是介词，再决定后面使用原形还是 -ing。本课应用：enjoy 后接 fishing 而非 to fish；after spending 中 after 是介词，后面用动名词。描述兴趣时不需要把每个动作都写成进行时。</p><p><strong>L20 原创例句：</strong> Ben enjoys fishing beside the old bridge.</p><p>本喜欢在旧桥旁钓鱼。</p><p><strong>易错：</strong> enjoy to fish 不是标准搭配；enjoy fishing 才表达喜欢钓鱼。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-020">Lesson 20</a></p>',23)])])}const h=o(i,[["render",r]]);export{u as __pageData,h as default};
